{
  "name": "Zaber 电动位移台单轴",
  "name_en": "Zaber motorized stage axis",
  "manufacturer": "Zaber Technologies",
  "description": "Zaber ASCII 协议控制的电动位移平台或线性执行器中的单个运动轴，用于实验中样品、光学元件或探头的精密定位、回零、相对/绝对位移和速度控制。",
  "description_en": "A single motion axis of a Zaber ASCII-controlled motorized stage or linear actuator, used in laboratories for precise positioning of samples, optical components, or probes, including homing, relative/absolute moves, and velocity control.",
  "tag_hints": [
    "motorized linear stage",
    "precision positioning",
    "multi-axis motion control",
    "homing",
    "serial ASCII control",
    "optomechanical alignment"
  ],
  "actions": [
    {
      "action_name": "auto-send",
      "description": "向该轴发送 ASCII 运动或查询命令。",
      "description_en": "Send an ASCII motion or query command to this axis."
    },
    {
      "action_name": "auto-home",
      "description": "使该轴回零并建立参考位置。",
      "description_en": "Home the axis to establish a reference position."
    },
    {
      "action_name": "auto-move_abs",
      "description": "将该轴移动到指定绝对位置。",
      "description_en": "Move the axis to a specified absolute position."
    },
    {
      "action_name": "auto-move_rel",
      "description": "使该轴相对当前位置移动指定距离。",
      "description_en": "Move the axis by a specified relative distance."
    },
    {
      "action_name": "auto-move_vel",
      "description": "使该轴以指定速度连续运动。",
      "description_en": "Move the axis continuously at a specified velocity."
    },
    {
      "action_name": "auto-stop",
      "description": "立即停止该轴运动。",
      "description_en": "Stop the axis motion immediately."
    },
    {
      "action_name": "auto-poll_until_idle",
      "description": "等待该轴完成运动并进入空闲状态。",
      "description_en": "Wait until the axis finishes moving and becomes idle."
    },
    {
      "action_name": "auto-get_status",
      "description": "获取该轴的运动状态。",
      "description_en": "Get the axis motion status."
    },
    {
      "action_name": "auto-encode",
      "description": "将命令编码为设备可识别的 ASCII 报文。",
      "description_en": "Encode a command into an ASCII message recognized by the device."
    },
    {
      "action_name": "auto-axis",
      "description": "选择或获取指定编号的运动轴。",
      "description_en": "Select or access a specified numbered axis."
    },
    {
      "action_name": "auto-write",
      "description": "向设备串口写入原始指令数据。",
      "description_en": "Write raw command data to the device serial port."
    },
    {
      "action_name": "auto-read",
      "description": "从设备串口读取回复数据。",
      "description_en": "Read reply data from the device serial port."
    },
    {
      "action_name": "auto-flush",
      "description": "清空设备串口通信缓冲区。",
      "description_en": "Flush the device serial communication buffer."
    },
    {
      "action_name": "auto-timeout",
      "description": "定义串口通信超时时间。",
      "description_en": "Define the serial communication timeout."
    },
    {
      "action_name": "auto-baudrate",
      "description": "定义串口通信波特率。",
      "description_en": "Define the serial communication baud rate."
    }
  ]
}

